(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.MathFamilyRewards=api;})(typeof window==='object'?window:globalThis,function(){
 'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const gem='<svg class="diamond-mark" viewBox="0 0 48 40" aria-hidden="true"><path d="M10 2h28l9 12-23 25L1 14Z" fill="#d4edff" stroke="#7aa6c8" stroke-width="1.5"/><path d="m10 2 5 12 9-12 9 12 5-12M1 14h46M15 14l9 25 9-25" fill="none" stroke="#7aa6c8" stroke-width="1.5"/><path d="m24 2-9 12h18Z" fill="#f3fbff"/></svg>';
 function home(wallet){return `<div class="growth-wallet"><div class="growth-wallet-balance">${gem}<div><span>我的钻石</span><strong>${wallet?wallet.available:'—'}<small>钻</small></strong></div><p>${wallet?.reserved?`${wallet.reserved} 钻待家长确认`:`每天打卡 +${wallet?.rules?.daily??5} 钻`}</p></div><div class="growth-wallet-actions"><button class="btn small dark" data-action="family-store">兑换家庭奖励 <span>→</span></button><button class="link-btn" data-action="family-history">收支记录</button></div></div>`;}
 function history(wallet){if(!wallet)return '<p>登录学习空间后查看钻石记录。</p>';return `<p class="sub">可用 ${wallet.available} 钻 · 待确认 ${wallet.reserved} 钻 · 累计获得 ${wallet.earned} 钻</p><p class="note-line">历史学习天数继续保留；钻石从本功能启用当天开始积累。</p>${wallet.events.map(e=>`<div class="reward-history-row"><div><strong>${esc(e.detail.title)}</strong><small>${new Date(e.created*1000).toLocaleDateString('zh-CN')}</small></div><b class="${e.amount>0?'income':''}">${e.amount>0?'+':''}${e.amount} 钻</b></div>`).join('')||'<p class="sub">完成今天的五题，或订正答对一道错题，就能收到第一笔钻石。</p>'}`;}
 function store(wallet){if(!wallet)return '<p>正在同步钻石，请稍后重试。</p>';const rate=wallet.rules.points_per_diamond;return `<div class="reward-store-intro">${gem}<div><strong>${wallet.available}<small> 钻可用</small></strong><p>1 钻 = ${rate} 家庭积分 · 由家长确认兑换</p></div></div><div class="reward-catalog">${wallet.rules.catalog.map((r,i)=>`<article><span class="reward-art art-${i%3}">${['✦','✿','☀'][i%3]}</span><div><h3>${esc(r.title)}</h3><p>${r.cost} 钻 · 对应 ${r.cost*rate} 家庭积分</p></div><button class="btn small ${wallet.available>=r.cost?'dark':''}" data-family-reward="${esc(r.id)}" ${wallet.available<r.cost?'disabled':''}>${wallet.available>=r.cost?'申请兑换':'还差 '+(r.cost-wallet.available)+' 钻'}</button></article>`).join('')}</div><p class="note-line">申请后先预留钻石；家长确认后记入家庭兑换，退回后钻石恢复可用。奖励内容和分值由家长调整。</p>${requests(wallet,false)}`;}
 function requests(wallet,parent){return (wallet?.requests||[]).length?`<h3 class="reward-request-heading">${parent?'兑换申请':'我的兑换申请'}</h3>${wallet.requests.map(r=>`<div class="reward-request-row"><div><strong>${esc(r.title)}</strong><small>${r.diamonds} 钻 · ${r.points} 家庭积分</small></div><span class="reward-status ${r.status}">${{pending:'待家长确认',approved:'已确认兑换',rejected:'已退回，钻石返还'}[r.status]}</span>${parent&&r.status==='pending'?`<div class="row"><button class="btn small dark" data-family-decision="approved" data-family-request="${esc(r.id)}">确认兑换</button><button class="link-btn" data-family-decision="rejected" data-family-request="${esc(r.id)}">退回</button></div>`:''}</div>`).join('')}`:'<p class="sub">暂时没有兑换申请。</p>';}
 function parent(wallet){return `<section class="panel family-parent-panel"><div class="section-head"><div><div class="eyebrow">家庭奖励 · 家长管理</div><h2>把每一点努力，变成小期待。</h2></div>${gem}</div><p class="sub">孩子通过每日学习获得钻石，家庭奖励由你确认。现有学习记录继续保留。</p><div class="row" style="margin-top:18px"><button class="btn dark" data-action="family-parent">管理兑换${wallet?'（'+wallet.requests.filter(r=>r.status==='pending').length+'）':''}</button><button class="btn" data-action="family-rules">调整积分与奖励</button></div><p class="note-line">确认兑换和修改规则时，需要再次输入本学习空间的家庭密码。</p></section>`;}
 function management(wallet){return `<label class="form-label" for="family-parent-password">家长验证：本学习空间的家庭密码</label><input class="field" type="password" id="family-parent-password" autocomplete="off" placeholder="只用于本次确认，不会保存在页面"><p class="note-line">确认后，请在家里安排对应奖励；当前记录保存在这个孩子的学习空间。</p>${requests(wallet,true)}`;}
 function rules(wallet){if(!wallet)return '<p>请先连接学习空间。</p>';const r=wallet.rules;return `<form id="family-rules-form"><div class="reward-rule-grid"><label>每日打卡奖励（钻）<input class="field" type="number" min="1" max="50" id="reward-rule-daily" value="${r.daily}" required></label><label>1钻对应家庭积分<input class="field" type="number" min="1" max="100" id="reward-rule-rate" value="${r.points_per_diamond}" required></label>${[3,7,14,30].map(n=>`<label>累计${n}天额外奖励（钻）<input class="field" type="number" min="0" max="500" id="reward-rule-${n}" value="${r.milestones[n]}" required></label>`).join('')}</div><h3>家庭奖励</h3>${r.catalog.map((item,i)=>`<div class="reward-rule-item"><label>奖励名称<input class="field" id="reward-title-${i}" maxlength="60" value="${esc(item.title)}" required></label><label>所需钻石<input class="field" id="reward-cost-${i}" type="number" min="1" max="10000" value="${item.cost}" required></label></div>`).join('')}<label class="form-label" for="family-rules-password">家庭密码</label><input class="field" id="family-rules-password" type="password" autocomplete="off" required><p class="note-line">调整只影响之后的新奖励；已到账钻石和已提交兑换保留原分值。</p><button class="btn dark" type="submit">保存家庭规则</button></form>`;}
 return Object.freeze({home,store,history,parent,management,rules});
});
